define([],function(){"use strict";function getCards(hub){return Array.prototype.slice.call(hub.querySelectorAll(".flw-video-card"))}function renderPage(hub,cards,page,pageSize,status,previous,next){var totalPages=Math.max(1,Math.ceil(cards.length/pageSize));var currentPage=Math.min(Math.max(page,0),totalPages-1);var start=currentPage*pageSize;var end=start+pageSize;cards.forEach(function(card,index){card.hidden=index<start||index>=end});status.textContent=currentPage+1+" / "+totalPages;previous.disabled=currentPage===0;next.disabled=currentPage>=totalPages-1;hub.setAttribute("data-current-page",String(currentPage+1));return currentPage}function initHub(hub){if(hub.getAttribute("data-flw-pagination-ready")==="1"){return}var cards=getCards(hub);var pageSize=parseInt(hub.getAttribute("data-page-size")||"0",10);if(!cards.length||!pageSize||cards.length<=pageSize){return}hub.setAttribute("data-flw-pagination-ready","1");var pager=document.createElement("nav");var previous=document.createElement("button");var next=document.createElement("button");var status=document.createElement("span");var page=0;pager.className="flw-video-pager";pager.setAttribute("aria-label","Video pages");previous.type="button";next.type="button";previous.textContent="Previous";next.textContent="Next";previous.setAttribute("aria-label","Show previous videos");next.setAttribute("aria-label","Show next videos");status.setAttribute("aria-live","polite");pager.appendChild(previous);pager.appendChild(status);pager.appendChild(next);hub.appendChild(pager);previous.addEventListener("click",function(){page=renderPage(hub,cards,page-1,pageSize,status,previous,next)});next.addEventListener("click",function(){page=renderPage(hub,cards,page+1,pageSize,status,previous,next)});page=renderPage(hub,cards,page,pageSize,status,previous,next)}function init(root){var container=root||document;Array.prototype.slice.call(container.querySelectorAll(".flw-video-hub[data-page-size]")).forEach(initHub)}return{init:init}});
